import {escapeHtml as h,number} from './domain.js';
export function unitLevel(value){if(value==null||!Number.isFinite(Number(value))||!Number.isInteger(Number(value)))return '<span class="unit-level unknown" title="Répartition historique non enregistrée">N? historique</span>';return `<span class="unit-level" title="Niveau technologique des unités">N${Math.max(0,Number(value))}</span>`;}
export function forceLevelGroups(forces,key,fallbackRace){const groups=new Map();for(const f of forces){const race=f.race||fallbackRace,quantity=key==='soldiers'?Number(f.ground_soldiers||0)+Number(f.soldiers||0):Number(f[key]||0),cohorts=f.unit_cohorts?.[key];const entries=cohorts?cohortEntries(cohorts,quantity):[[Number.isInteger(Number(f[key==='soldiers'?'army_tech':'ship_tech']))?f[key==='soldiers'?'army_tech':'ship_tech']:null,quantity]];for(const [raw,n] of entries){if(!Number(n))continue;const level=raw==='legacy'||raw==null?null:Number(raw),id=race+':'+level;if(!groups.has(id))groups.set(id,{race,level,quantity:0});groups.get(id).quantity+=Number(n);}}return [...groups.values()].sort((a,b)=>String(a.race).localeCompare(String(b.race))||Number(a.level)-Number(b.level));}
export function forceLevelBadges(forces,key,race){return forceLevelGroups(forces,key,race).map(g=>`<span class="force-level-count">${unitLevel(g.level)}<small>×${number(g.quantity)}</small></span>`).join('');}

function cohortEntries(cohorts,quantity){const rows=Object.entries(cohorts).filter(([,n])=>Number(n)>0),total=rows.reduce((n,[,v])=>n+Number(v),0);if(total<=quantity)return rows;const parts=rows.map(([level,n])=>{const exact=quantity*Number(n)/total;return {level,n:Math.floor(exact),rem:exact-Math.floor(exact)};}).sort((a,b)=>b.rem-a.rem||a.level.localeCompare(b.level));let rest=quantity-parts.reduce((n,p)=>n+p.n,0);for(const p of parts)if(rest-->0)p.n++;return parts.map(p=>[p.level,p.n]);}
